mapper.select:
select id, entrust_mix_area, entrusted_mix_area, material_name, create_by, create_time, update_by, update_time,
del_flag, remark from t_lhfl_span_setting
where del_flag = '0'
and entrust_mix_area = #{entrustMixArea}
and entrusted_mix_area = #{entrustedMixArea}

and INSTR(material_name, #{materialName}) > 0

    order by create_time desc


    order by ${orderStr}

WITH temp_table AS (
SELECT #{rowNumber}+2 row_numbers, #{data.entrustMixArea,jdbcType=VARCHAR} entrust_mix_area, #{data.entrustedMixArea,jdbcType=VARCHAR} entrusted_mix_area, #{data.materialName,jdbcType=VARCHAR} material_name
) select #{importLogId} importLogId, t.row_numbers errorRow, #{errorDetail} errorDetail, #{createBy} createBy, now() createTime from t_lhfl_span_setting m inner join temp_table t on m.entrust_mix_area = t.entrust_mix_area and m.material_name = t.material_name and m.del_flag ='0'

mapper.insert:
insert into t_lhfl_span_setting
(id,entrust_mix_area,entrusted_mix_area,material_name,create_by,create_time,update_by,update_time,del_flag,remark
)
select NULL id, x.*
from (

    select
    #{lhflSpanSetting.entrustMixArea,jdbcType= VARCHAR} entrust_mix_area,
    #{lhflSpanSetting.entrustedMixArea,jdbcType= VARCHAR} entrusted_mix_area,
    #{lhflSpanSetting.materialName,jdbcType= VARCHAR} material_name,
    #{lhflSpanSetting.createBy,jdbcType= VARCHAR} create_by, #{lhflSpanSetting.createTime,jdbcType=TIMESTAMP}
    create_time, #{lhflSpanSetting.updateBy,jdbcType= VARCHAR} update_by,
    #{lhflSpanSetting.updateTime,jdbcType=TIMESTAMP} update_time, #{lhflSpanSetting.delFlag,jdbcType= VARCHAR}
    del_flag, #{lhflSpanSetting.remark,jdbcType= VARCHAR} remark 

) x
